message.content:
{ 
"description": "The creature in the image is shown in strict side profile facing right against a plain off-white background. From the head to the mid-body and wings it has the appearance of a large brown raptor, with dense layered brown feathers, folded wings, and thick feathered legs ending in large yellow scaly feet with black talons. The head is that of an eagle with a hooked beak and a golden eye. The posterior, where a feathered tail would normally be, instead bears a hanging cluster of fleshy, sucker-lined tentacle-like appendages. Circular sucker discs are also visible on the skin of the lower legs/thighs. The overall impression is a single upright standing bird-like body with a raptor front half and tentacles at the rear.",
"parts": [
  {
    "part": "head",
    "looks_like": "large raptor head in right profile, covered in short brown feathers on crown and neck, with a prominent hooked beak that is dark gray at the tip and yellow at the cere and gape, a round golden-brown eye with a dark pupil and a pale gray area around the nostril, facing to the right at the top of the body"
  ,
    "where": "at the top front of the body, atop the feathered neck"
  },
  {
    "part": "legs",
    "looks_like": "two thick, upright, heavily feathered legs, brown feathered thighs and shanks with patches of bare-looking skin bearing rows of circular white-rimmed sucker discs on the front and side surfaces",
    "where": "extending down from the lower belly to the feet, one slightly forward of the other"
  },
  {
    "part": "feet",
    "looks_like": "large yellow scaly feet with thick textured scales, each with four toes bearing long, sharply curved black talons",
    "where": "at the bottom ends of the two walking legs, in contact with the ground"
  },
  {
    "part": "wings",
    "looks_like": "two large folded wings with overlapping brown feathers in varying shades of tan to dark brown, each feather with a darker edge giving a scaled appearance, long primary feathers pointed at the rear",
    "where": "on the left and right sides of the back and torso, folded against the body, the left wing fully visible in profile"
  },
  {
    "part": "tail",
    "looks_like": "not a normal feathered tail; the tail region is formed by a cluster of about seven fleshy, tapered, brownish tentacle-like appendages hanging vertically, each lined on the inner side with two rows of circular suckers, tips curling inward",
    "where": "at the posterior of the body, below the tips of the folded wings, hanging down behind the legs"
  },
  {
    "part": "tentacles",
    "looks_like": "same as tail: fleshy, muscular, brown with mottled darker patches, tapered to curled tips, undersides covered in numerous small circular suckers with light rims",
    "where": "emerging together from the rear/vent area and hanging down as the tail"
  },
  {
    "part": "feathers",
    "looks_like": "dense plumage covering head, neck, chest, back, wings and upper legs, individual feathers detailed with barbs and shading from light golden-brown on the neck to darker brown on the wings and back",
    "where": "over most of the body except the beak, feet, sucker patches and tentacles"
  },
  {
    "part": "markings",
    "looks_like": "circular sucker discs with central pits and pale rims, arranged in clusters on the front of both thighs/shanks and in rows along the tentacles",
    "where": "on the skin of the lower legs and on the entire length of the tail tentacles"
  }
],
"attached_objects": [],
"animals": ["eagle", "octopus"],
"separate_bodies": 1,
"heads": 1,
"walking_legs": 2,
"wings": 2,
"extra_limb_pieces": 0
}
